upstream api_backend {
  server 127.0.0.1:8000 max_fails=3 fail_timeout=30s;
  server 127.0.0.1:8001 backup;
  keepalive 32;
}
server {
  listen 80;
  server_name app.example.com;
  return 301 https://$host$request_uri;
}
server {
  listen 443 ssl http2;
  server_name app.example.com;
  ssl_certificate /etc/ssl/certs/app.example.com.crt;
  ssl_certificate_key /etc/ssl/private/app.example.com.key;
  ssl_protocols TLSv1.2 TLSv1.3;
[PARTIAL - output truncated at 70 lines, continue reading remainder for location blocks]

  access_log /var/log/nginx/app.access.log combined;
  error_log /var/log/nginx/app.error.log warn;
  location / {
    proxy_pass http://api_backend;
    proxy_set_header Host $host;
    proxy_set_header X-Real-IP $remote_addr;
    proxy_set_header X-Forwarded-For $proxy_add_x_forwarded_for;
    proxy_set_header X-Forwarded-Proto $scheme;
    proxy_http_version 1.1;
    proxy_set_header Connection "";
  }
  location /static/ {
    alias /var/www/app/static/;
    expires 30d;
    add_header Cache-Control "public, immutable";
  }
  location /healthz {
    access_log off;
    return 200 "ok";
  }
}
# production: http redirects to https, api proxied with keepalive, static cached 30d, healthz for probes.

