:root {
  --bg: #ffffff;
  --fg: #1a1a1a;
  --brand: #0b5fff;
  --muted: #6b7280;
  --border: #e5e7eb;
  --radius: 8px;
  --maxw: 1120px;
}
* { box-sizing: border-box; }
html, body { margin: 0; padding: 0; background: var(--bg); color: var(--fg); font-family: Inter, Arial, sans-serif; }
.container { max-width: var(--maxw); margin: 0 auto; padding: 0 16px; }
.header { display: flex; align-items: center; justify-content: space-between; height: 64px; border-bottom: 1px solid var(--border); }
.nav { display: flex; gap: 16px; }
.nav a { color: var(--muted); text-decoration: none; font-weight: 600; }
.nav a.active { color: var(--brand); }
.hero { padding: 48px 0 32px 0; text-align: left; }
.hero h1 { font-size: 36px; margin: 0 0 12px 0; }
