.grid { display: grid; grid-template-columns: repeat(3, 1fr); gap: 20px; }
.card { border: 1px solid var(--border); border-radius: var(--radius); padding: 16px; background: #fff; }
.card h3 { margin: 0 0 8px 0; font-size: 18px; }
.card p { margin: 0; color: var(--muted); font-size: 14px; }
.footer { margin-top: 40px; padding: 24px 0; border-top: 1px solid var(--border); color: var(--muted); font-size: 14px; }
.btn { display: inline-block; padding: 10px 18px; border-radius: 6px; background: var(--brand); color: #fff; }
.btn.secondary { background: #fff; color: var(--brand); border: 1px solid var(--brand); }
@media (max-width: 900px) {
  .grid { grid-template-columns: repeat(2, 1fr); }
  .hero { padding: 32px 0 20px 0; }
}
@media (max-width: 600px) {
  .grid { grid-template-columns: 1fr; }
  .nav { gap: 10px; }
  .header { height: 56px; }
}
